                    releaseRepository.incrementRoundStats(snapshot.releaseId(), request.result());
                    if (request.result() == ReceiptResult.SUCCESS) {
                        // 锁设备行后同时推进固件版本与配置版本，并整体替换为领取时冻结的迁移后配置
